/**
 * Generated by `createservice miniapp.ImportB2BAppService`
 */

const { faker } = require('@faker-js/faker')

const {
    makeClient,
    expectToThrowAccessDeniedErrorToResult,
    expectToThrowAuthenticationErrorToResult,
    expectToThrowGQLErrorToResult,
} = require('@open-hearth/keystone/test.utils')

const { SMART_HOME_CATEGORY, BUSINESS_DEVELOPMENT_CATEGORY } = require('@hearth/domains/miniapp/constants')
const { getDevicePermissions, getDevicePermissionFieldName } = require('@hearth/domains/miniapp/schema/fields/devicePermissions')
const { createTestOidcClient } = require('@hearth/domains/user/utils/testSchema')
const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS } = require('@dev-portal-api/domains/miniapp/constants/b2bAppAccessRightSet')
const { PUBLISH_REQUEST_APPROVED_STATUS, AVAILABLE_ENVIRONMENTS, DEV_ENVIRONMENT, PROD_ENVIRONMENT } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const {
    B2BApp,
    B2BAppPublishRequest,
    B2BAppAccessRight,
    B2BAppAccessRightSet,
    HearthB2BApp,
    HearthB2BAppAccessRight,
    HearthOIDCClient,
    createTestB2CApp,
    createOIDCClientByTestClient,
    createTestB2BApp,
    createHearthB2BApp,
    createTestB2BAppPublishRequest,
    importB2BAppByTestClient,
    publishB2BAppByTestClient,
    createHearthB2BAppAccessRight,
} = require('@dev-portal-api/domains/miniapp/utils/testSchema')
const { makeLoggedInAdminClient, makeLoggedInSupportClient, makeRegisteredAndLoggedInUser, makeLoggedInHearthAdminClient } = require('@dev-portal-api/domains/user/utils/testSchema')

const { getEnvironmentalFieldName } = require('./fields/environmental')

describe('ImportB2BAppService', () => {
    let admin
    let support
    let hearthAdmin
    let user
    let anonymous
    let app
    let hearthDevApp
    let hearthProdApp
    beforeAll(async () => {
        admin = await makeLoggedInAdminClient()
        hearthAdmin = await makeLoggedInHearthAdminClient()
        support = await makeLoggedInSupportClient()
        user = await makeRegisteredAndLoggedInUser()
        anonymous = await makeClient()
    })
    describe('Access tests', () => {
        beforeEach(async () => {
            [app] = await createTestB2BApp(user);
            [hearthDevApp] = await createHearthB2BApp(hearthAdmin);
            [hearthProdApp] = await createHearthB2BApp(hearthAdmin)
        })
        test('Admin can import any app', async () => {
            const [result] = await importB2BAppByTestClient(admin, app, hearthDevApp, hearthProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('Support can import any app', async () => {
            const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, hearthProdApp)
            expect(result).toHaveProperty('success', true)
        })
        test('App owner cannot import app', async () => {
            await expectToThrowAccessDeniedErrorToResult(async () => {
                await importB2BAppByTestClient(user, app, hearthDevApp, hearthProdApp)
            })
        })
        test('Anonymous cannot import app', async () => {
            await expectToThrowAuthenticationErrorToResult(async () => {
                await importB2BAppByTestClient(anonymous, app, hearthDevApp, hearthProdApp)
            })
        })
    })
    describe('Logic tests', () => {
        describe('Basic checks', () => {
            test('Must throw on empty "from" input', async () => {
                const [app] = await createTestB2BApp(user)
                await expectToThrowGQLErrorToResult(async () => {
                    await importB2BAppByTestClient(support, app, null, null)
                }, {
                    code: 'BAD_USER_INPUT',
                    type: 'ARG_NOT_SPECIFIED',
                })
            })
            test('Must throw on invalid "to" input', async () => {
                const [hearthApp] = await createHearthB2BApp(hearthAdmin)
                await expectToThrowGQLErrorToResult(async () => {
                    await importB2BAppByTestClient(support, { id: faker.datatype.uuid() }, hearthApp, null)
                }, {
                    code: 'BAD_USER_INPUT',
                    type: 'APP_NOT_FOUND',
                })
            })
        })
        describe('App info', () => {
            let devPermissions
            let prodPermissions
            beforeEach(async () => {
                [app] = await createTestB2BApp(user)
                devPermissions = {}
                prodPermissions = {}

                for (const permission of getDevicePermissions({ listKey: 'B2BApp' })) {
                    const fieldName = getDevicePermissionFieldName(permission)
                    devPermissions[fieldName] = faker.datatype.boolean()
                    prodPermissions[fieldName] = faker.datatype.boolean()
                }

                [hearthDevApp] = await createHearthB2BApp(hearthAdmin, {
                    developerUrl: faker.internet.url(),
                    shortDescription: faker.lorem.sentence(),
                    detailedDescription: faker.lorem.paragraph(),
                    category: SMART_HOME_CATEGORY,
                    contextDefaultStatus: 'InProgress',
                    appUrl: `https://${faker.internet.domainName()}`,
                    ...devPermissions,
                });
                [hearthProdApp] = await createHearthB2BApp(hearthAdmin, {
                    developerUrl: faker.internet.url(),
                    shortDescription: faker.lorem.sentence(),
                    detailedDescription: faker.lorem.paragraph(),
                    category: BUSINESS_DEVELOPMENT_CATEGORY,
                    contextDefaultStatus: 'Finished',
                    appUrl: `https://${faker.internet.domainName()}`,
                    ...prodPermissions,
                })
            })
            test('App must be updated with info from hearth dev app if prod app is not specified', async () => {
                const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, null)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', hearthDevApp.name)
                expect(updatedApp).toHaveProperty('developer', hearthDevApp.developer)
                expect(updatedApp).toHaveProperty('developerUrl', hearthDevApp.developerUrl)
                expect(updatedApp).toHaveProperty('shortDescription', hearthDevApp.shortDescription)
                expect(updatedApp).toHaveProperty('detailedDescription', hearthDevApp.detailedDescription)
                expect(updatedApp).toHaveProperty('category', hearthDevApp.category)
                expect(updatedApp).toHaveProperty('contextDefaultStatus', hearthDevApp.contextDefaultStatus)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], hearthDevApp.logo.originalFilename)
                expect(updatedApp).toHaveProperty('developmentExportId', hearthDevApp.id)
            })
            test('App must be updated with info from hearth prod app if prod app is specified', async () => {
                const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                expect(updatedApp).toHaveProperty('name', hearthProdApp.name)
                expect(updatedApp).toHaveProperty('developer', hearthProdApp.developer)
                expect(updatedApp).toHaveProperty('developerUrl', hearthProdApp.developerUrl)
                expect(updatedApp).toHaveProperty('shortDescription', hearthProdApp.shortDescription)
                expect(updatedApp).toHaveProperty('detailedDescription', hearthProdApp.detailedDescription)
                expect(updatedApp).toHaveProperty('category', hearthProdApp.category)
                expect(updatedApp).toHaveProperty('contextDefaultStatus', hearthProdApp.contextDefaultStatus)
                expect(updatedApp).toHaveProperty(['logo', 'originalFilename'], hearthProdApp.logo.originalFilename)
                expect(updatedApp).toHaveProperty('productionExportId', hearthProdApp.id)
            })
            test('Hearth apps must be updated to include importId and importRemoteSystem', async () => {
                const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedDevApp = await HearthB2BApp.getOne(hearthAdmin, { id: hearthDevApp.id })
                expect(updatedDevApp).toHaveProperty('importId', app.id)
                expect(updatedDevApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                const updatedProdApp = await HearthB2BApp.getOne(hearthAdmin, { id: hearthProdApp.id })
                expect(updatedProdApp).toHaveProperty('importId', app.id)
                expect(updatedProdApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
            })
            test('Environmental fields must be imported as well', async () => {
                const [dummyApp] = await createTestB2CApp(user)
                const [secondDummyApp] = await createTestB2CApp(user)
                const [{ id: oidcClientId }] = await createOIDCClientByTestClient(user, dummyApp)
                const [{ id: secondOidcClientId }] = await createOIDCClientByTestClient(user, secondDummyApp)
                await HearthB2BApp.update(hearthAdmin, hearthDevApp.id, {
                    dv: 1,
                    sender: { dv: 1, fingerprint: 'test-utilities' },
                    oidcClient: { connect: { id: oidcClientId } },
                })
                await HearthB2BApp.update(hearthAdmin, hearthProdApp.id, {
                    dv: 1,
                    sender: { dv: 1, fingerprint: 'test-utilities' },
                    oidcClient: { connect: { id: secondOidcClientId } },
                })

                const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const updatedApp = await B2BApp.getOne(support, { id: app.id })
                const expectedPayload = {}
                for (const environment of AVAILABLE_ENVIRONMENTS) {
                    const app = environment === DEV_ENVIRONMENT ? hearthDevApp : hearthProdApp
                    const clientId = environment === DEV_ENVIRONMENT ? oidcClientId : secondOidcClientId
                    expectedPayload[getEnvironmentalFieldName(environment, 'appUrl')] = app.appUrl
                    expectedPayload[getEnvironmentalFieldName(environment, 'oidcClientId')] = clientId

                    const permissionsObj = environment === DEV_ENVIRONMENT ? devPermissions : prodPermissions
                    for (const [field, value] of Object.entries(permissionsObj)) {
                        const envFieldName = getEnvironmentalFieldName(environment, field.substring(2))
                        expectedPayload[envFieldName] = value
                    }
                }

                expect(updatedApp).toEqual(expect.objectContaining(expectedPayload))
            })
            test('Hearth OIDC client must be updated with importId / importRemoteSystem if not taken', async () => {
                const [firstClient] = await createTestOidcClient(hearthAdmin)
                const [secondClient] = await createTestOidcClient(hearthAdmin, { importId: '1234', importRemoteSystem: 'my-test-system' })
                const [firstApp] = await createHearthB2BApp(hearthAdmin, { oidcClient: { connect: { id: firstClient.id } } })
                const [secondApp] = await createHearthB2BApp(hearthAdmin, { oidcClient: { connect: { id: secondClient.id } } })

                const [app] = await createTestB2BApp(user)
                const [result] = await importB2BAppByTestClient(support, app, firstApp, secondApp)
                expect(result).toHaveProperty('success', true)

                const firstClientAfter = await HearthOIDCClient.getOne(hearthAdmin, { id: firstClient.id })
                expect(firstClientAfter).toHaveProperty('importId', app.id)
                expect(firstClientAfter).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                const secondClientAfter = await HearthOIDCClient.getOne(hearthAdmin, { id: secondClient.id })
                expect(secondClientAfter).toHaveProperty('importId', '1234')
                expect(secondClientAfter).toHaveProperty('importRemoteSystem', 'my-test-system')
            })
        })
        describe('B2BAppAccessRight + B2BAppAccessRightSet', () => {
            test('Right set models must be created correctly', async () => {
                const [hearthDevApp] = await createHearthB2BApp(hearthAdmin)
                const [hearthProdApp] = await createHearthB2BApp(hearthAdmin)
                const [hearthDevRight, , devPermissions] = await createHearthB2BAppAccessRight(hearthAdmin, hearthDevApp)
                const [hearthProdRight, , prodPermissions] = await createHearthB2BAppAccessRight(hearthAdmin, hearthProdApp)

                const [app] = await createTestB2BApp(user)
                const [result] = await importB2BAppByTestClient(support, app, hearthDevApp, hearthProdApp)
                expect(result).toHaveProperty('success', true)

                const devRight = await B2BAppAccessRight.getOne(support, { app: { id: app.id }, environment: DEV_ENVIRONMENT })
                expect(devRight).toHaveProperty('hearthUserId', hearthDevRight.user.id)
                expect(devRight).toHaveProperty('developmentExportId', hearthDevRight.id)
                expect(devRight).toHaveProperty('productionExportId', null)
                const devRightSet = await B2BAppAccessRightSet.getOne(support, { app: { id: app.id }, environment: DEV_ENVIRONMENT })
                expect(devRightSet).toHaveProperty('status', B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS)
                expect(devRightSet).toHaveProperty('developmentExportId', hearthDevRight.accessRightSet.id)
                expect(devRightSet).toHaveProperty('productionExportId', null)
                expect(devRightSet).toEqual(expect.objectContaining(devPermissions))
                const hearthDevRightAfter = await HearthB2BAppAccessRight.getOne(hearthAdmin, { id: hearthDevRight.id })
                expect(hearthDevRightAfter).toHaveProperty('importId', devRight.id)
                expect(hearthDevRightAfter).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                expect(hearthDevRightAfter).toHaveProperty(['accessRightSet', 'importId'], devRightSet.id)
                expect(hearthDevRightAfter).toHaveProperty(['accessRightSet', 'importRemoteSystem'], REMOTE_SYSTEM)

                const prodRight = await B2BAppAccessRight.getOne(support, { app: { id: app.id }, environment: PROD_ENVIRONMENT })
                expect(prodRight).toHaveProperty('hearthUserId', hearthProdRight.user.id)
                expect(prodRight).toHaveProperty('developmentExportId', null)
                expect(prodRight).toHaveProperty('productionExportId', hearthProdRight.id)
                const prodRightSet = await B2BAppAccessRightSet.getOne(support, { app: { id: app.id }, environment: PROD_ENVIRONMENT })
                expect(prodRightSet).toHaveProperty('status', B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS)
                expect(prodRightSet).toHaveProperty('developmentExportId', null)
                expect(prodRightSet).toHaveProperty('productionExportId', hearthProdRight.accessRightSet.id)
                expect(prodRightSet).toEqual(expect.objectContaining(prodPermissions))
                const hearthProdRightAfter = await HearthB2BAppAccessRight.getOne(hearthAdmin, { id: hearthProdRight.id })
                expect(hearthProdRightAfter).toHaveProperty('importId', prodRight.id)
                expect(hearthProdRightAfter).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                expect(hearthProdRightAfter).toHaveProperty(['accessRightSet', 'importId'], prodRightSet.id)
                expect(hearthProdRightAfter).toHaveProperty(['accessRightSet', 'importRemoteSystem'], REMOTE_SYSTEM)
            })
        })
        describe('B2BAppPublishRequest', () => {
            test('Publish request in approved status must be created if imported from production environment', async () => {
                const [hearthApp] = await createHearthB2BApp(hearthAdmin)
                const [firstApp] = await createTestB2BApp(user)
                const [result] = await importB2BAppByTestClient(support, firstApp, null, hearthApp)
                expect(result).toHaveProperty('success', true)

                const request = await B2BAppPublishRequest.getOne(user, { app: { id: firstApp.id } })
                expect(request).toHaveProperty('status', PUBLISH_REQUEST_APPROVED_STATUS)

                const [secondHearthApp] = await createHearthB2BApp(hearthAdmin)
                const [secondApp] = await createTestB2BApp(user)
                const [secondResult] = await importB2BAppByTestClient(support, secondApp, secondHearthApp, null)
                expect(secondResult).toHaveProperty('success', true)

                const secondRequest = await B2BAppPublishRequest.getOne(user, { app: { id: secondApp.id } })
                expect(secondRequest).not.toBeDefined()
            })
        })
        describe('Conflict policy', () => {
            describe.each(AVAILABLE_ENVIRONMENTS)('%p environment', (environment) => {
                let fromApp
                beforeEach(async () => {
                    // Create app - it auto-publishes and gets linked to a hearth app
                    [app] = await createTestB2BApp(user)
                    if (environment !== DEV_ENVIRONMENT) {
                        await createTestB2BAppPublishRequest(support, app, {
                            isAppTested: true,
                            isContractSigned: true,
                            isInfoApproved: true,
                            status: PUBLISH_REQUEST_APPROVED_STATUS,
                        })
                    }
                    await publishB2BAppByTestClient(support, app, undefined, environment);
                    // Create a different hearth app that we'll try to import - this creates a conflict
                    [fromApp] = await createHearthB2BApp(hearthAdmin)
                })
                test('Must throw error on conflict if conflictPolicy is set to "panic"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    await expectToThrowGQLErrorToResult(async () => {
                        await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'panic' } })
                    }, {
                        code: 'INTERNAL_ERROR',
                        type: 'MULTIPLE_FOUND',
                    })
                })
                test('Must unlink conflicting app if conflictPolicy is set to "setNull"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked hearth app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2BApp.getOne(support, { id: app.id })
                    const originalHearthAppId = appBefore[exportField]
                    expect(originalHearthAppId).not.toBeNull()

                    const [result] = await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'setNull' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await HearthB2BApp.getOne(hearthAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)

                    // Check that the originally auto-linked hearth app was unlinked (importId set to null)
                    const originalHearthApp = await HearthB2BApp.getOne(hearthAdmin, { id: originalHearthAppId })
                    expect(originalHearthApp).toHaveProperty('importId', null)
                    expect(originalHearthApp).toHaveProperty('importRemoteSystem', null)
                })
                test('Must delete previously linked app if conflictPolicy is set to "delete"', async () => {
                    const devApp = environment === DEV_ENVIRONMENT ? fromApp : null
                    const prodApp = devApp ? null : fromApp
                    // Get the originally auto-linked hearth app before import
                    const exportField = environment === DEV_ENVIRONMENT ? 'developmentExportId' : 'productionExportId'
                    const appBefore = await B2BApp.getOne(support, { id: app.id })
                    const originalHearthAppId = appBefore[exportField]
                    expect(originalHearthAppId).not.toBeNull()

                    const [result] = await importB2BAppByTestClient(support, app, devApp, prodApp, { options: { conflictPolicy: 'delete' } })
                    expect(result).toHaveProperty('success', true)

                    // Check that fromApp is now linked to the dev-portal app
                    const updatedFromApp = await HearthB2BApp.getOne(hearthAdmin, { id: fromApp.id })
                    expect(updatedFromApp).toHaveProperty('importId', app.id)
                    expect(updatedFromApp).toHaveProperty('importRemoteSystem', REMOTE_SYSTEM)
                    expect(updatedFromApp).toHaveProperty('deletedAt', null)

                    // Check that the originally auto-linked hearth app was soft-deleted
                    const originalHearthApp = await HearthB2BApp.getOne(hearthAdmin, { id: originalHearthAppId })
                    expect(originalHearthApp).not.toBeDefined()
                })
            })
        })
    })
})